const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const MAX=6*1024*1024,types=new Set(['image/jpeg','image/png','image/webp','audio/mp4','audio/x-m4a','audio/mpeg','audio/webm','audio/ogg','audio/wav','audio/x-wav']);
