export const workStateLabel=state=>({submitted:'Ждёт проверки',accepted:'Принято',needs_revision:'Нужно доработать'}[state]||'Ещё не отправлено');
const safeUrl=(value,upload=false)=>{const url=new URL(value);if(url.origin!==project||!url.pathname.startsWith('/storage/v1/object/'+(upload?'upload/sign/':'sign/')+bucket+'/')||!url.searchParams.has('token')||url.username||url.password||url.hash)throw Error('Не удалось открыть защищённый файл.');return url.href;};
export async function uploadWorkFile(file,call,{signal,fetcher=fetch}={}){
 const mime=(file.type||'').split(';')[0].toLowerCase();if(!types.has(mime)||file.size<12||file.size>MAX)throw Error('Нужны фото JPG, PNG, WebP или аудио до 6 МБ.');
 const prepared=await call('prepare-work-file',{mime,bytes:file.size});if(signal?.aborted)throw Error('Загрузка отменена.');
 const controller=new AbortController(),abort=()=>controller.abort(),timer=setTimeout(abort,90000);signal?.addEventListener('abort',abort,{once:true});
 try{const form=new FormData();form.append('cacheControl','0');form.append('',file,file.name||'homework');const response=await fetcher(safeUrl(prepared.uploadUrl,true),{method:'PUT',body:form,headers:{'x-upsert':'false'},credentials:'omit',redirect:'error',signal:controller.signal});if(!response.ok)throw Error('Не удалось загрузить файл. Повторите.');return(await call('finish-work-file',{fileId:prepared.file.id})).file;}
 finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}
}
export async function openWorkFile(file,call){const result=await call('work-file',{fileId:file.id});return safeUrl(result.url);}
function fileContent(doc,file,url){const media=doc.createElement(file.kind==='audio'?'audio':'img');media.src=url;if(file.kind==='audio'){media.controls=true;media.preload='none';}else{media.alt='Фото выполненного задания';media.loading='lazy';media.decoding='async';}media.referrerPolicy='no-referrer';return media;}
