 const form=root.querySelector('form'),answer=form.querySelector('textarea'),submit=form.querySelector('[type=submit]'),record=form.querySelector('[data-record]'),filesRoot=form.querySelector('[data-files]'),error=form.querySelector('[data-error]'),status=root.querySelector('[data-work-state]'),feedback=root.querySelector('[data-feedback]'),recordStatus=form.querySelector('[data-record-status]');
