   claimPlayback(owner);setForegroundAudio(owner,true);recorder.start(1000);recording=true;permission=false;startAt=Date.now();recordStatus.textContent='Идёт запись · 0:00';recordClock=setInterval(()=>{if(active()){const seconds=Math.floor((Date.now()-startAt)/1000);recordStatus.textContent='Идёт запись · '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}},1000);recordTimer=setTimeout(()=>endRecord(),180000);dirty=true;update();
