 const invoke=(action,data={})=>call(action,{id:lesson.id,...data});
 root.innerHTML='<section class="homework-work"><h2>Работы учеников</h2><p class="homework-hint">Текст, голосовые записи и фото видны только ученику и преподавателю.</p><button class="lesson-text-button" data-refresh type="button">Обновить работы</button><p role="status" data-status></p><div data-works></div></section>';
 const status=root.querySelector('[data-status]'),list=root.querySelector('[data-works]');
 async function refresh(){const version=++epoch;status.textContent='Загружаем работы…';try{const result=await invoke('work-list');if(!active()||version!==epoch)return;for(const editor of readingEditors)editor.dispose();readingEditors=[];const rows=result.works.filter(work=>!studentId||work.userId===studentId);if(rows.some(work=>work.readingCheck))readingUiModule=await loadReadingUi();if(!active()||version!==epoch)return;list.replaceChildren();status.textContent=rows.length?'Работ: '+rows.length:studentId?'Ученик ещё не отправил работу.':'Ученики ещё не отправили ДЗ.';
  for(const work of rows){const card=doc.createElement('article');card.className='homework-submitted';card.innerHTML='<div class="homework-submitted-head"><h3>'+esc(work.nickname)+'</h3><span class="homework-state">'+esc(workStateLabel(work.state))+'</span></div>'+(work.homeworkRevision!==lesson.homeworkRevision?'<p class="homework-hint">Предыдущее задание · версия '+esc(work.homeworkRevision)+'</p>':'')+'<p class="homework-hint">Отправлено '+esc(new Date(work.submittedAt).toLocaleString('ru-RU'))+'</p>'+(work.text?'<p class="homework-answer" dir="auto">'+esc(work.text)+'</p>':'')+'<div data-files></div><div data-reading-review></div><form><label>Комментарий ученику<textarea rows="3" maxlength="2000">'+esc(work.feedback||'')+'</textarea></label><p role="alert"></p><div class="button-row"><button class="button" type="submit" name="accepted">Принять</button><button class="button secondary" type="submit" name="needs_revision">На доработку</button></div></form>';
   const files=card.querySelector('[data-files]');for(const file of work.files||[]){const box=doc.createElement('div');box.className='homework-file';const button=doc.createElement('button');button.type='button';button.className='button secondary';button.textContent=file.kind==='audio'?'Послушать запись':'Посмотреть фото';button.onclick=async()=>{button.disabled=true;try{const url=await resolveFile(file,invoke);if(active()&&card.isConnected){box.append(fileContent(doc,file,url));button.remove();}}catch(e){if(active())card.querySelector('[role=alert]').textContent=e.message;button.disabled=false;}};box.append(button);files.append(box);}
   const readingReview=work.readingCheck?readingUiModule.mountReadingReview(card.querySelector('[data-reading-review]'),{check:work.readingCheck,initial:work.readingReview}):null;if(readingReview)readingEditors.push(readingReview);
   const form=card.querySelector('form');let saving=false;form.onsubmit=async event=>{event.preventDefault();if(saving)return;const state=event.submitter?.name||'accepted',feedback=form.querySelector('textarea').value.trim(),error=form.querySelector('[role=alert]');let readingResult=null;try{readingResult=readingReview?.value()||null;}catch(e){error.textContent=e.message;return;}if(state==='needs_revision'&&!feedback&&!readingResult){error.textContent='Подскажите ученику, что нужно исправить.';return;}if(feedback.length>2000){error.textContent='Сократите комментарий до 2000 символов.';return;}saving=true;for(const button of form.querySelectorAll('button'))button.disabled=true;try{await invoke('review-work',{studentId:work.userId,homeworkRevision:work.homeworkRevision,expectedVersion:work.version,state,feedback,...(readingResult?{readingMarks:readingResult.marks}:{})});if(active())await refresh();}catch(e){if(active()&&card.isConnected){error.textContent=e.message;saving=false;for(const button of form.querySelectorAll('button'))button.disabled=false;}}};list.append(card);
  }
 }catch(e){if(active()&&version===epoch)status.textContent=e.message;}}
 root.querySelector('[data-refresh]').onclick=()=>void refresh();void refresh();
 return()=>{disposed=true;epoch++;for(const editor of readingEditors)editor.dispose();readingEditors=[];root.querySelectorAll('audio').forEach(audio=>audio.pause());root.replaceChildren();};
